import type { MetadataRoute } from "next";
import { cacheLife, cacheTag } from "next/cache";
import { db } from "@/lib/db";
import { SITE } from "@/lib/site";
import { TAGS } from "@/lib/tags";

async function entries() {
  "use cache";
  cacheLife("hours");
  cacheTag(TAGS.products, TAGS.categories);
  const [categories, products] = await Promise.all([
    db.category.findMany({ where: { isActive: true }, select: { slug: true, updatedAt: true } }),
    db.product.findMany({ where: { isActive: true }, select: { slug: true, updatedAt: true } }),
  ]);
  return { categories, products };
}

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const { categories, products } = await entries();
  const statics = ["", "/search", "/b2b", "/engraving", "/gallery", "/contact", "/policies/shipping", "/policies/returns", "/policies/privacy", "/policies/terms"].map((p) => ({
    url: `${SITE.url}${p}`,
    changeFrequency: "weekly" as const,
    priority: p === "" ? 1 : 0.6,
  }));
  return [
    ...statics,
    ...categories.map((c) => ({ url: `${SITE.url}/category/${c.slug}`, lastModified: c.updatedAt, changeFrequency: "daily" as const, priority: 0.8 })),
    ...products.map((p) => ({ url: `${SITE.url}/product/${p.slug}`, lastModified: p.updatedAt, changeFrequency: "weekly" as const, priority: 0.7 })),
  ];
}
